{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case fields")
    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError("invalid case field types")
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError("required symbols must be strings")

    required_node_fields = ("id", "parent", "symbol", "depth", "removable", "utility")
    by_id = {}
    order = []
    for node in nodes:
        if not isinstance(node, dict) or any(field not in node for field in required_node_fields):
            raise ValueError("invalid node")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("node IDs must be unique strings")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("invalid parent")
        if not isinstance(symbol, str):
            raise ValueError("invalid symbol")
        if isinstance(depth, bool) or not isinstance(depth, int):
            raise ValueError("invalid depth")
        if not isinstance(removable, bool):
            raise ValueError("invalid removable flag")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("invalid utility")
        by_id[node_id] = node
        order.append(node_id)

    roots = [node_id for node_id in order if by_id[node_id]["parent"] is None]
    if len(roots) != 1:
        raise ValueError("parse tree must have one root")
    for node_id in order:
        parent = by_id[node_id]["parent"]
        if parent is not None and parent not in by_id:
            raise ValueError("parent must reference an existing node")

    retained = set(order)
    removed = []
    candidates = sorted(
        (by_id[node_id] for node_id in order),
        key=lambda node: (-node["depth"], node["id"]),
    )
    for node in candidates:
        node_id = node["id"]
        if not node["removable"] or node["parent"] is None or node_id not in retained:
            continue
        if any(other["parent"] == node_id and other["id"] in retained for other in nodes):
            continue
        trial_symbols = {
            other["symbol"] for other in nodes if other["id"] in retained and other["id"] != node_id
        }
        if all(symbol in trial_symbols for symbol in required_symbols):
            retained.remove(node_id)
            removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }"}
